import pandas as pd


def clean(df):
    df = df.copy()
    category_map = {
        'accessories': 'Accessories',
        'Furnture': 'Furniture',
        'office supplies': 'Office Supplies',
    }
    df['Category'] = df['Category'].map(lambda x: category_map.get(x, x) if pd.notna(x) else x)
    df = df.drop_duplicates()
    return df


def answer(df):
    counts = df['Category'].value_counts().to_dict()
    return {k: int(v) for k, v in counts.items()}
